void nvfs_throw (NVFS_Status nvfs_status , const char * const file_name , const UInt32 file_line)
{
  nvfs_report   (nvfs_status , file_name , file_line , FALSE) ;

  longjmp       (*nvfs_vars.exception.throw_vec , 1) ;
}

